CREATE TABLE IF NOT EXISTS public.delete_requests (id BIGSERIAL PRIMARY KEY, user_id UUID NOT NULL REFERENCES public.users(id) ON DELETE CASCADE, requested_by UUID NOT NULL REFERENCES public.users(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), reviewed_by UUID REFERENCES public.users(id), reviewed_at TIMESTAMPTZ);
ALTER TABLE public.delete_requests ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.get_admin_users() RETURNS TABLE(user_id UUID,id_number VARCHAR,username VARCHAR,email VARCHAR,role VARCHAR,registration_status VARCHAR,is_locked_out BOOLEAN,created_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.users AS viewer WHERE viewer.id=auth.uid() AND viewer.role IN('admin','superadmin')) THEN RAISE EXCEPTION 'Only administrators can view users'; END IF; RETURN QUERY SELECT u.id,u.id_number,u.username,u.email,u.role,u.registration_status,u.is_locked_out,u.created_at FROM public.users AS u WHERE u.id<>auth.uid() ORDER BY u.created_at DESC; END $$;
CREATE OR REPLACE FUNCTION public.admin_update_user_status(p_user_id UUID,p_status TEXT) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.users AS viewer WHERE viewer.id=auth.uid() AND viewer.role IN('admin','superadmin')) THEN RAISE EXCEPTION 'Only administrators can update status'; END IF; IF p_status NOT IN('approved','blocked') THEN RAISE EXCEPTION 'Invalid status'; END IF; IF (SELECT viewer.role FROM public.users AS viewer WHERE viewer.id=auth.uid())='admin' AND (SELECT target.role FROM public.users AS target WHERE target.id=p_user_id)='superadmin' THEN RAISE EXCEPTION 'Administrators cannot modify superadmins'; END IF; UPDATE public.users SET registration_status=p_status,is_locked_out=(p_status='blocked') WHERE id=p_user_id; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.get_user_for_admin_edit(p_user_id UUID) RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE r JSONB; BEGIN IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role IN('admin','superadmin')) THEN RAISE EXCEPTION 'Only administrators can edit users'; END IF; SELECT jsonb_build_object('id_number',id_number,'username',username,'email',email) INTO r FROM public.users WHERE id=p_user_id; RETURN r; END $$;
CREATE OR REPLACE FUNCTION public.admin_update_user_profile(p_user_id UUID,p_id_number TEXT,p_username TEXT,p_email TEXT) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role IN('admin','superadmin')) THEN RAISE EXCEPTION 'Only administrators can edit users'; END IF; UPDATE public.users SET id_number=p_id_number,username=p_username,email=p_email WHERE id=p_user_id; RETURN FOUND; END $$;
CREATE OR REPLACE FUNCTION public.create_delete_request(p_user_id UUID,p_reason TEXT) RETURNS BIGINT LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE rid BIGINT; BEGIN IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role='admin') THEN RAISE EXCEPTION 'Only administrators can request deletion'; END IF; IF (SELECT role FROM public.users WHERE id=p_user_id)='superadmin' THEN RAISE EXCEPTION 'Administrators cannot request deletion of superadmins'; END IF; IF length(trim(p_reason))<3 THEN RAISE EXCEPTION 'A deletion reason is required'; END IF; INSERT INTO public.delete_requests(user_id,requested_by,reason) VALUES(p_user_id,auth.uid(),trim(p_reason)) RETURNING id INTO rid; RETURN rid; END $$;
DROP FUNCTION IF EXISTS public.get_delete_requests();
CREATE OR REPLACE FUNCTION public.get_delete_requests() RETURNS TABLE(request_id BIGINT,user_id UUID,id_number VARCHAR,username VARCHAR,email VARCHAR,first_name VARCHAR,middle_initial VARCHAR,last_name VARCHAR,suffix VARCHAR,birthdate DATE,age INT,sex VARCHAR,purok VARCHAR,barangay VARCHAR,city VARCHAR,province VARCHAR,country VARCHAR,zip VARCHAR,reason TEXT,requested_by UUID,created_at TIMESTAMPTZ) LANGUAGE plpgsql SECURITY DEFINER AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role='superadmin') THEN RAISE EXCEPTION 'Only superadmins can view deletion requests'; END IF; RETURN QUERY SELECT d.id,u.id,u.id_number,u.username,u.email,p.first_name,p.middle_initial,p.last_name,p.suffix,p.birthdate,p.age,p.sex,a.purok,a.barangay,a.city,a.province,a.country,a.zip,d.reason,d.requested_by,d.created_at FROM public.delete_requests d JOIN public.users u ON u.id=d.user_id LEFT JOIN public.profiles p ON p.user_id=u.id LEFT JOIN public.addresses a ON a.user_id=u.id WHERE d.status='pending' ORDER BY d.created_at; END $$;
CREATE OR REPLACE FUNCTION public.review_delete_request(p_request_id BIGINT,p_approve BOOLEAN) RETURNS BOOLEAN LANGUAGE plpgsql SECURITY DEFINER AS $$ DECLARE target UUID; BEGIN IF NOT EXISTS(SELECT 1 FROM public.users WHERE id=auth.uid() AND role='superadmin') THEN RAISE EXCEPTION 'Only superadmins can review deletion requests'; END IF; SELECT user_id INTO target FROM public.delete_requests WHERE id=p_request_id AND status='pending'; IF target IS NULL THEN RETURN FALSE; END IF; IF p_approve THEN DELETE FROM public.users WHERE id=target; END IF; UPDATE public.delete_requests SET status=CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,reviewed_by=auth.uid(),reviewed_at=now() WHERE id=p_request_id; RETURN TRUE; END $$;
